mapper.select:
SELECT * FROM rom_db
WHERE system_id = #{systemId} AND serial = #{serial}
LIMIT 1

SELECT * FROM rom_db
WHERE system_id = #{systemId}
  AND (REPLACE(serial, '-', '') = #{gameCode}
       OR REPLACE(serial, '-', '') LIKE CONCAT(#{gameCode}, '0%')
       OR REPLACE(serial, '-', '') LIKE CONCAT(#{gameCode}, ',%'))
LIMIT 1

SELECT * FROM rom_db
WHERE system_id = #{systemId} AND crc32 = #{crc32}
LIMIT 1

SELECT * FROM rom_db
WHERE platform = #{platform} AND serial = #{serial}
LIMIT 1

SELECT * FROM rom_db
WHERE platform = #{platform} AND crc32 = #{crc32}
LIMIT 1

SELECT * FROM rom_db
WHERE system_id = #{systemId}
  AND LOWER(game_name) LIKE LOWER('%' || #{keyword} || '%')
ORDER BY game_name
LIMIT #{limit}
